import { redis } from '@packages/utils';
import { logger } from '@packages/observability';
import { v4 as uuidv4 } from 'uuid';
import { NotificationService } from './notification-service.js';

export type ApprovalStatus = 'PENDING' | 'APPROVED' | 'REJECTED' | 'EXPIRED';

export interface ApprovalRequest {
  id: string;
  createdAt: number;
  expiresAt: number;
  risk: 'LOW' | 'MEDIUM' | 'HIGH';
  reliabilityScore: number;
  
  // Decision Context
  proposedAction: any;
  predictedImpact: number;
  rootCauses: { nodeId: string; confidence: number }[];
  
  // Safety
  blastRadius: number;
  targetServices: string[];
  
  // Explainability
  reasoning: string;
  
  status: ApprovalStatus;
  decidedBy?: string;
  decisionReason?: string;
}

export class ApprovalService {
  private static KEY_PREFIX = 'sre:approval:';
  private static LIST_KEY = 'sre:approval:active';

  public static async createRequest(params: Omit<ApprovalRequest, 'id' | 'createdAt' | 'status'>): Promise<ApprovalRequest> {
    const id = uuidv4();
    const req: ApprovalRequest = {
      ...params,
      id,
      createdAt: Date.now(),
      status: 'PENDING'
    };

    await redis.set(`${this.KEY_PREFIX}${id}`, JSON.stringify(req), 'PX', params.expiresAt - Date.now());
    await redis.lpush(this.LIST_KEY, id);
    
    logger.info({ requestId: id, proposedAction: params.proposedAction.type, reliabilityScore: params.reliabilityScore }, '[APPROVAL] New request created');
    
    // Trigger External Notification
    await NotificationService.notifyApprovalRequired(id, params.proposedAction.type, params.reliabilityScore);
    
    return req;
  }

  public static async getRequest(id: string): Promise<ApprovalRequest | null> {
    const data = await redis.get(`${this.KEY_PREFIX}${id}`);
    return data ? JSON.parse(data) : null;
  }

  public static async approve(id: string, user: string, reason?: string): Promise<ApprovalRequest | null> {
    const req = await this.getRequest(id);
    if (!req || req.status !== 'PENDING') return null;

    req.status = 'APPROVED';
    req.decidedBy = user;
    req.decisionReason = reason;

    await redis.set(`${this.KEY_PREFIX}${id}`, JSON.stringify(req));
    logger.info({ requestId: id, user }, '[APPROVAL] Request approved');
    return req;
  }

  public static async reject(id: string, user: string, reason?: string): Promise<ApprovalRequest | null> {
    const req = await this.getRequest(id);
    if (!req || req.status !== 'PENDING') return null;

    req.status = 'REJECTED';
    req.decidedBy = user;
    req.decisionReason = reason;

    await redis.set(`${this.KEY_PREFIX}${id}`, JSON.stringify(req));
    logger.warn({ requestId: id, user, reason }, '[APPROVAL] Request rejected');
    return req;
  }

  public static async getActiveRequests(): Promise<ApprovalRequest[]> {
    const ids = await redis.lrange(this.LIST_KEY, 0, -1);
    const requests = await Promise.all(ids.map((id: string) => this.getRequest(id)));
    return requests.filter((r): r is ApprovalRequest => r !== null && r.status === 'PENDING');
  }
}

import { exec } from 'child_process';
import path from 'path';
import fs from 'fs';
import { Groq } from 'groq-sdk';
import util from 'util';
import crypto from 'node:crypto';
import { ThresholdCrypto } from '@packages/ztan-crypto';
import type { PatchIntent } from '@packages/ztan-crypto';

const execAsync = util.promisify(exec);

export class DevinAutoHealer {
    private groq: Groq;
    private maxRetries = 2; // Strict limit to prevent infinite loops

    constructor() {
        this.groq = new Groq({ apiKey: process.env.GROQ_API_KEY });
    }

    async healProject(projectId: string, dir: string): Promise<boolean> {
        console.log(`[AutoHealer] Commencing autonomous heal bounds for module '${projectId}' in ${dir}`);

        // Ensure dependencies are installed
        console.log(`[AutoHealer] Resolving sub-dependencies...`);
        let depsInstalled = await this.runCommand(dir, 'npm install --no-audit --legacy-peer-deps --loglevel=error');

        if (!depsInstalled.success) {
            console.warn(`[AutoHealer] Initial dependency resolution failed. Analyzing stderr...`);
            const fixedDeps = await this.tryHeal(dir, 'npm install', depsInstalled.error, depsInstalled.stdout);
            if (fixedDeps) {
                console.log(`[AutoHealer] Retrying dependency resolution post-patch...`);
                depsInstalled = await this.runCommand(dir, 'npm install --no-audit --legacy-peer-deps');
            }
            if (!depsInstalled.success) {
                console.log(`[AutoHealer] Critical failure in module dependency structure.`);
                return false;
            }
        }

        console.log(`[AutoHealer] Checking environment syntactic validity...`);
        // If there's a build script, run it. Otherwise assume valid.
        const pkgPath = path.join(dir, 'package.json');
        if (fs.existsSync(pkgPath)) {
            const pkgInfo = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
            if (pkgInfo.scripts && pkgInfo.scripts.build && pkgInfo.dependencies && pkgInfo.dependencies.next) {

                let attempts = 0;
                let buildPhase = await this.runCommand(dir, 'npx tsc --noEmit || echo "TSC Passed" && npx next build');

                while (!buildPhase.success && attempts < this.maxRetries) {
                    attempts++;
                    console.error(`[AutoHealer] Static compilation failed. Bootstrapping AI repair protocol (Attempt ${attempts}/${this.maxRetries})...`);
                    console.error(`[AutoHealer] Cause: ${buildPhase.error.substring(0, 200)}...`);

                    const fixed = await this.tryHeal(dir, 'npx next build', buildPhase.error, buildPhase.stdout);
                    if (!fixed) {
                        console.log(`[AutoHealer] No generative fixes applied. Halting repair.`);
                        break;
                    }

                    console.log(`[AutoHealer] Recompiling container...`);
                    buildPhase = await this.runCommand(dir, 'npx tsc --noEmit || echo "TSC Passed" && npx next build');
                }

                if (buildPhase.success) {
                    console.log(`[AutoHealer] System successfully auto-healed code to pass deterministic builds!`);
                } else {
                    console.log(`[AutoHealer] Max retries exhausted. System is in unstable state, forcing graceful launch.`);
                }
            }
        }

        return true;
    }

    private async runCommand(dir: string, cmd: string): Promise<{ success: boolean, stdout: string, error: string }> {
        try {
            const { stdout, stderr } = await execAsync(cmd, { cwd: dir, timeout: 90000 });
            return { success: true, stdout, error: stderr };
        } catch (e: any) {
            return { success: false, stdout: e.stdout || '', error: e.stderr || e.message || '' };
        }
    }

    private async tryHeal(dir: string, command: string, stderr: string, stdout: string): Promise<boolean> {
        const files: { path: string, content: string }[] = [];
        this.readCodeDir(dir, '', files);

        try {
            const { RepairAgent } = require('../agents/repair-agent');
            const repairAgent = new RepairAgent();

            // Execute autonomous agent directly to heal the filesystem bounds
            const response = await repairAgent.execute(
                { error: stderr, stdout, files: files.slice(0, 20) },
                {} as any // Placeholder context, not strictly required for this localized agent
            );

            if (response.success && response.data?.patches?.length > 0) {
                console.log(`[AutoHealer] ${response.data.patches.length} potential patches identified.`);
                
                for (const patch of response.data.patches) {
                    // --- SECURITY: Path Traversal Validation (Priority 0) ---
                    const ALLOWED_ROOT = path.resolve(dir);
                    const resolvedPath = path.resolve(ALLOWED_ROOT, patch.path.startsWith('/') ? patch.path.slice(1) : patch.path);

                    if (!resolvedPath.startsWith(ALLOWED_ROOT)) {
                        console.error(`[AutoHealer] SECURITY ALERT: Path traversal attempt blocked: ${patch.path}`);
                        continue;
                    }

                    // --- SECURITY: Symlink Escape Validation ---
                    try {
                        const realPath = fs.realpathSync(resolvedPath);
                        if (!realPath.startsWith(ALLOWED_ROOT)) {
                            console.error(`[AutoHealer] SECURITY ALERT: Symlink escape detected and blocked: ${patch.path} -> ${realPath}`);
                            continue;
                        }
                    } catch (_e) {
                        // If file doesn't exist yet, we check the directory
                        const parentDir = path.dirname(resolvedPath);
                        if (fs.existsSync(parentDir)) {
                            const realParent = fs.realpathSync(parentDir);
                            if (!realParent.startsWith(ALLOWED_ROOT)) {
                                console.error(`[AutoHealer] SECURITY ALERT: Parent directory symlink escape: ${parentDir}`);
                                continue;
                            }
                        }
                    }

                    // --- SECURITY: Extension Allowlist ---
                    const ext = path.extname(resolvedPath).toLowerCase();
                    const ALLOWED_EXTENSIONS = ['.ts', '.tsx', '.js', '.json', '.yaml', '.yml', '.md'];
                    if (!ALLOWED_EXTENSIONS.includes(ext)) {
                        console.error(`[AutoHealer] SECURITY ALERT: Blocked patch for unauthorized extension: ${ext}`);
                        continue;
                    }

                    // --- SECURITY: Dry-Run Mode (Freeze Unsafe Mutation Paths) ---
                    console.log(`[AutoHealer] [DRY-RUN] Would apply surgical patch onto: ${patch.path}`);
                    
                    try { 
                        // ACTUAL WRITE DISABLED UNTIL OPERATOR APPROVAL SYSTEM IS IMPLEMENTED
                        // --- SECURITY: Patch Provenance & Intent Verification ---
                        const isApproved = await this.verifyPatchIntent(patch);
                        if (!isApproved && process.env.NODE_ENV === 'production') {
                            console.error(`[AutoHealer] SECURITY ALERT: Unsigned patch rejected in production: ${patch.path}`);
                            continue;
                        }

                        // --- DRY RUN: Finalized Execution ---
                        console.log(`[AutoHealer] [DRY-RUN] Would apply patch to ${patch.path} with hash ${this.calculateHash(patch.content)}`);
                        // fs.writeFileSync(resolvedPath, patch.content);
                    } catch (err) {
                        console.error(`[AutoHealer] Error processing patch for ${patch.path}:`, err);
                    }
                }
                return true;
            } else if (response.error) {
                console.error('[AutoHealer] RepairAgent evaluation failed:', response.error);
            }
        } catch (e) {
            console.error('[AutoHealer] Deep learning generator failed to evaluate patches.', e);
        }
        return false;
    }

    private readCodeDir(base: string, sub: string, out: any[]) {
        const fullPath = path.join(base, sub);
        if (!fs.existsSync(fullPath)) return;
        const entries = fs.readdirSync(fullPath, { withFileTypes: true });
        for (const e of entries) {
            if (e.name === 'node_modules' || e.name === '.next' || e.name.startsWith('.')) continue;
            const relPath = path.join(sub, e.name);
            if (e.isDirectory()) {
                this.readCodeDir(base, relPath, out);
            } else if (e.name.endsWith('.ts') || e.name.endsWith('.tsx') || e.name.endsWith('.js') || e.name === 'package.json') {
                out.push({ path: relPath, content: fs.readFileSync(path.join(base, relPath), 'utf8') });
            }
        }
    }

    /**
     * Verifies that a patch has been explicitly approved by a human operator.
     * Required for Phase B: Trust Provenance.
     */
    private async verifyPatchIntent(patch: any): Promise<boolean> {
        const intent = patch.intent as PatchIntent;
        if (!intent) {
            console.warn(`[AutoHealer] Missing PatchIntent for ${patch.path}`);
            return false;
        }

        try {
            const isValid = await ThresholdCrypto.verifyPatchIntent(intent, []);
            if (isValid) {
                console.log(`[AutoHealer] Verified context-bound operator signature for patch: ${patch.path}`);
                console.log(`- Epoch: ${intent.trustEpoch}`);
                console.log(`- Environment: ${intent.environment}`);
                console.log(`- Operator: ${intent.operatorId}`);
                return true;
            }
        } catch (e: any) {
            console.error(`[AutoHealer] Patch verification failed for ${patch.path}: ${e.message}`);
        }
        
        return false;
    }

    private calculateHash(content: string): string {
        return crypto.createHash('sha256').update(content).digest('hex');
    }
}

export const autoHealer = new DevinAutoHealer();

import { redis } from '@packages/utils';
import crypto from 'crypto';

export class CacheService {
    /**
     * Generates a deterministic hash for a prompt + context state.
     */
    static generateCacheKey(prompt: string, techStack: any): string {
        const raw = `${prompt}:${JSON.stringify(techStack)}`;
        return `codegen:${crypto.createHash('sha256').update(raw).digest('hex')}`;
    }

    /**
     * Saves code generation results (patches or full files) to Redis cache.
     * Caches expire after 7 days to prevent stale code drift.
     */
    static async setCachedResult(key: string, result: any, ttlSeconds: number = 7 * 24 * 60 * 60): Promise<void> {
        try {
            await redis.set(key, JSON.stringify(result), 'EX', ttlSeconds);
        } catch (error) {
            console.error('[CacheService] Failed to write cache', error);
        }
    }

    /**
     * Retrieves code generation results if they exist.
     */
    static async getCachedResult(key: string): Promise<any | null> {
        try {
            const cached = await redis.get(key);
            if (cached) {
                return JSON.parse(cached);
            }
        } catch (error) {
            console.error('[CacheService] Failed to read cache', error);
        }
        return null;
    }
}

import { redis } from '@packages/utils';
import { logger } from '@packages/observability';

export class CalibrationEngine {
  private static STORAGE_KEY = 'sre:calibration:samples';

  public static async recordSample(confidence: number, outcome: number, hypothesisType?: string, actualType?: string) {
    try {
      const samplesJson = await redis.get(this.STORAGE_KEY);
      const samples = samplesJson ? JSON.parse(samplesJson) : [];

      samples.push({
        time: new Date().toISOString(),
        confidence,
        outcome,
        hypothesisType,
        actualType
      });

      // Keep last 500 samples for calibration
      if (samples.length > 500) samples.shift();

      await redis.set(this.STORAGE_KEY, JSON.stringify(samples));
    } catch (err: any) {
      logger.warn({ err }, '[CALIBRATION] Failed to record sample in redis');
    }
  }

  public static async calculateHypothesisPrecision(type: string): Promise<number> {
    try {
      const samplesJson = await redis.get(this.STORAGE_KEY);
      if (!samplesJson) return 1.0;

      const samples = JSON.parse(samplesJson);
      const relevant = samples.filter((s: any) => s.hypothesisType === type);
      if (relevant.length === 0) return 1.0;

      const correct = relevant.filter((s: any) => s.outcome === 1.0).length;
      return correct / relevant.length;
    } catch (err: any) {
      logger.warn({ err }, '[CALIBRATION] Failed to calculate hypothesis precision from redis');
      return 1.0;
    }
  }

  public static async calculateRecall(type: string): Promise<number> {
    try {
      const samplesJson = await redis.get(this.STORAGE_KEY);
      if (!samplesJson) return 1.0;

      const samples = JSON.parse(samplesJson);
      // Recall: Predicted_Anomaly / Actual_Anomaly
      const actualAnomalies = samples.filter((s: any) => s.actualType === type);
      if (actualAnomalies.length === 0) return 1.0;

      const correctlyPredicted = actualAnomalies.filter((s: any) => s.hypothesisType === type).length;
      return correctlyPredicted / actualAnomalies.length;
    } catch (err: any) {
      logger.warn({ err }, '[CALIBRATION] Failed to calculate recall from redis');
      return 1.0;
    }
  }

  public static async getSupportCount(type: string, isActual: boolean = false): Promise<number> {
    try {
      const samplesJson = await redis.get(this.STORAGE_KEY);
      if (!samplesJson) return 0;

      const samples = JSON.parse(samplesJson);
      return samples.filter((s: any) => isActual ? s.actualType === type : s.hypothesisType === type).length;
    } catch (err: any) {
      logger.warn({ err }, '[CALIBRATION] Failed to get support count from redis');
      return 0;
    }
  }

  public static async calculateF1(type: string): Promise<number> {
    const precision = await this.calculateHypothesisPrecision(type);
    const recall = await this.calculateRecall(type);
    if (precision + recall === 0) return 0;
    return 2 * (precision * recall) / (precision + recall);
  }

  /**
   * Calculate Brier Score: Mean Squared Error of predictions
   * Ranges from 0.0 (Perfect) to 1.0 (Total Failure)
   */
  public static async calculateBrierScore(): Promise<number> {
    try {
      const samplesJson = await redis.get(this.STORAGE_KEY);
      if (!samplesJson) return 0;

      const samples = JSON.parse(samplesJson);
      if (samples.length === 0) return 0;

      const squaredErrors = samples.map((s: any) => Math.pow(s.confidence - s.outcome, 2));
      const meanSquaredError = squaredErrors.reduce((a: number, b: number) => a + b, 0) / samples.length;

      return meanSquaredError;
    } catch (err: any) {
      logger.warn({ err }, '[CALIBRATION] Failed to calculate Brier score from redis');
      return 0;
    }
  }

  public static async getAnomalyArrivalRate(): Promise<number> {
    try {
      const samplesJson = await redis.get(this.STORAGE_KEY);
      if (!samplesJson) return 0;

      const samples = JSON.parse(samplesJson);
      const anomalies = samples.filter((s: any) => s.actualType && s.actualType !== 'NOMINAL');
      if (anomalies.length === 0) return 0;

      const first = new Date(samples[0].time).getTime();
      const last = new Date(samples[samples.length - 1].time).getTime();
      const durationHours = (last - first) / (3600 * 1000);

      return anomalies.length / (durationHours || 1);
    } catch (err: any) {
      logger.warn({ err }, '[CALIBRATION] Failed to get anomaly arrival rate from redis');
      return 0;
    }
  }

  public static async isStatisticallySignificant(type: string): Promise<boolean> {
    const support = await this.getSupportCount(type, true);
    const rate = await this.getAnomalyArrivalRate();
    
    // Significance requires at least 30 samples OR enough to cover the expected rate
    const minSupport = Math.max(30, rate * 6); // 6-hour coverage equivalent
    return support >= minSupport;
  }
}

import * as Y from 'yjs';
import { db as prisma } from '@packages/db';
import logger from '@packages/utils';

/**
 * CollaborationPersistence
 * 
 * Production-ready Yjs persistence using Postgres.
 * Handles loading initial document state and persisting incremental updates.
 */
export class CollaborationPersistence {
    /**
     * Binds a Yjs document to Postgres persistence.
     * Loads the initial state from DB if it exists.
     */
    async bindState(docName: string, ydoc: Y.Doc) {
        try {
            const doc = await prisma.collaborativeDoc.findUnique({
                where: { name: docName }
            });

            if (doc && doc.updates) {
                Y.applyUpdate(ydoc, doc.updates);
                logger.debug({ docName }, '[YJS:Persistence] Initial state loaded from Postgres');
            } else {
                logger.debug({ docName }, '[YJS:Persistence] No existing state found, starting fresh');
            }

            // Listen for updates and persist them
            ydoc.on('update', async (_update: Uint8Array) => {
                await this.storeUpdate(docName, ydoc);
            });
        } catch (err) {
            logger.error({ docName, err }, '[YJS:Persistence] Failed to bind document state');
        }
    }

    public async load(docName: string): Promise<Uint8Array | null> {
        const doc = await prisma.collaborativeDoc.findUnique({
            where: { name: docName }
        });
        return doc?.updates ? new Uint8Array(doc.updates) : null;
    }

    public async save(docName: string, update: Uint8Array): Promise<void> {
        await prisma.collaborativeDoc.upsert({
            where: { name: docName },
            update: { updates: Buffer.from(update) },
            create: { 
                name: docName, 
                updates: Buffer.from(update) 
            }
        });
    }

    /**
     * Merges current document state and persists to Postgres.
     */
    private async storeUpdate(docName: string, ydoc: Y.Doc) {
        try {
            const state = Y.encodeStateAsUpdate(ydoc);
            await this.save(docName, state);
        } catch (err) {
            logger.error({ docName, err }, '[YJS:Persistence] Failed to store document update');
        }
    }
}

export const collaborationPersistence = new CollaborationPersistence();

import { logger } from '@packages/observability';

export interface DecisionInput {
  anomalyScore: number;
  burnRate: number;
}

export type SreDecision =
  | 'NO_ACTION'
  | 'OBSERVE'
  | 'ALERT'
  | 'ACT';

/**
 * DecisionEngine: Converts signals (Anomaly Score) and impact (Burn Rate)
 * into deterministic operational decisions.
 */
export class DecisionEngine {
  /**
   * Decide the next action based on signal strength and SLO impact.
   */
  public decide(input: DecisionInput): SreDecision {
    // 1. Critical Impact + Confirmed Anomaly -> ACT
    if (input.burnRate > 5 && input.anomalyScore > 0.7) {
      return 'ACT';
    }

    // 2. High Burn Rate -> ALERT (Even if anomaly is weak, impact is high)
    if (input.burnRate > 2) {
      return 'ALERT';
    }

    // 3. Signal Breach -> OBSERVE (Signal is high, but budget impact is low)
    if (input.anomalyScore > 0.7) {
      return 'OBSERVE';
    }

    return 'NO_ACTION';
  }
}

export const decisionEngine = new DecisionEngine();

