import { logger } from '@packages/observability';

export interface ConvergenceStats {
  velocity: number;
  velocityDecay: number; // ΔVelocity
  directionFlips: number;
  driftFromBaseline: number;
  state: 'INITIALIZING' | 'CONVERGING' | 'OSCILLATING' | 'FORMALLY_STABLE';
  isStable: boolean;
}

export class ConvergenceMonitor {
  private static HISTORY_KEY = 'sre:tuning:history';
  private static BASELINE_KEY = 'sre:tuning:original_baseline';

  public static async recordTuning(params: any) {
    const historyJson = await redis.get(this.HISTORY_KEY);
    const history = historyJson ? JSON.parse(historyJson) : [];
    
    history.push({ params, timestamp: Date.now() });
    if (history.length > 50) history.shift(); // Keep last 50 cycles

    await redis.set(this.HISTORY_KEY, JSON.stringify(history));
    
    // Save the very first tuning as the original baseline if it doesn't exist
    const baseline = await redis.get(this.BASELINE_KEY);
    if (!baseline) {
      await redis.set(this.BASELINE_KEY, JSON.stringify(params));
    }
  }

  public static async getStats(paramName: string): Promise<ConvergenceStats> {
    const historyJson = await redis.get(this.HISTORY_KEY);
    const history = historyJson ? JSON.parse(historyJson) : [];
    const baselineJson = await redis.get(this.BASELINE_KEY);
    const baseline = baselineJson ? JSON.parse(baselineJson) : null;

    if (history.length < 5) {
      return { velocity: 0, velocityDecay: 0, directionFlips: 0, driftFromBaseline: 0, state: 'INITIALIZING', isStable: true };
    }

    const values = history.map((h: any) => h.params[paramName]).filter((v: any) => v !== undefined);
    
    // Calculate Velocity (Rate of change)
    const velocity = (values[values.length - 1] - values[0]) / values.length;

    // Calculate Velocity Decay (Rate of rate of change)
    const midPoint = Math.floor(values.length / 2);
    const v1 = (values[midPoint] - values[0]) / midPoint;
    const v2 = (values[values.length - 1] - values[midPoint]) / (values.length - midPoint);
    const velocityDecay = Math.abs(v2) - Math.abs(v1); // Negative = Settling

    // Calculate Direction Flips
    let flips = 0;
    for (let i = 2; i < values.length; i++) {
      const prevDelta = values[i-1] - values[i-2];
      const currDelta = values[i] - values[i-1];
      if ((prevDelta > 0 && currDelta < 0) || (prevDelta < 0 && currDelta > 0)) {
        flips++;
      }
    }

    // Calculate Drift from Baseline
    const drift = baseline ? Math.abs(values[values.length - 1] - baseline[paramName]) : 0;

    let state: ConvergenceStats['state'] = 'CONVERGING';
    if (flips >= 3) state = 'OSCILLATING';
    else if (Math.abs(velocity) < 0.01 && velocityDecay <= 0) state = 'FORMALLY_STABLE';

    return {
      velocity,
      velocityDecay,
      directionFlips: flips,
      driftFromBaseline: drift,
      state,
      isStable: state === 'FORMALLY_STABLE' || state === 'CONVERGING'
    };
  }

  /**
   * Checks if the system is formally stable based on tuning velocity.
   */
  public static async checkStability(): Promise<boolean> {
    const stats = await this.getStats('dampingFactor');
    return stats.isStable;
  }
}

import type { SCMNode, SimulationResult } from './scm.types.js';

export class CounterfactualEngine {
  constructor(private nodes: SCMNode[]) {}

  /**
   * Simulates a "do-operator" intervention on the causal graph.
   * "What if we force node X to value V?"
   */
  public simulate(
    currentState: Record<string, number>,
    intervention: Record<string, number>
  ): Record<string, number> {
    // 1. Clone current state
    const state = { ...currentState };

    // 2. Apply interventions (do-operator)
    // Intervened nodes are "pinned" to the specific value and don't change based on parents.
    Object.keys(intervention).forEach(nodeId => {
      state[nodeId] = intervention[nodeId];
    });

    // 3. Propagate changes through the graph using a simple topological approach.
    // We sort nodes by their dependency depth to ensure parent values are computed before children.
    const sortedNodes = this.topologicalSort(this.nodes);

    for (const node of sortedNodes) {
      // Skip if this node was explicitly intervened on
      if (intervention[node.id] !== undefined) continue;

      const inputs: Record<string, number> = {};
      for (const parentId of node.parents) {
        inputs[parentId] = state[parentId] !== undefined ? state[parentId] : 0.01;
      }

      // Apply causal function
      state[node.id] = node.fn(inputs);
    }

    return state;
  }

  private topologicalSort(nodes: SCMNode[]): SCMNode[] {
    const sorted: SCMNode[] = [];
    const visited = new Set<string>();
    const visiting = new Set<string>();

    const visit = (node: SCMNode) => {
      if (visited.has(node.id)) return;
      if (visiting.has(node.id)) return; 

      visiting.add(node.id);
      for (const parentId of node.parents) {
        const parent = nodes.find(n => n.id === parentId);
        if (parent) visit(parent);
      }
      visiting.delete(node.id);
      visited.add(node.id);
      sorted.push(node);
    };

    nodes.forEach(n => visit(n));
    return sorted;
  }

  public computeSystemHealth(state: Record<string, number>): number {
    // Lower anomaly scores = Better health
    const values = Object.values(state);
    if (values.length === 0) return 1.0;
    const avgAnomaly = values.reduce((a, b) => a + b, 0) / values.length;
    return Math.max(0, 1.0 - avgAnomaly);
  }
}

import { redis } from '@packages/utils';
import { logger } from '@packages/observability';

export interface BaselineProfile {
  ttac: { p50: number; p95: number; p99: number; variance: number };
  disorder: { mean: number; p95: number; stdDev: number };
  brier: { mean: number; stability: number };
  divergenceKL: number;
  wassersteinDistance: number;
  timestamp: string;
}

export class DistributionAnalyzer {
  private static SHORT_WINDOW_KEY = 'sre:baseline:snapshots:short';
  private static LONG_WINDOW_KEY = 'sre:baseline:snapshots:long';

  public static async generateProfile(): Promise<BaselineProfile | null> {
    const snapshotsJson = await redis.get(this.LONG_WINDOW_KEY);
    if (!snapshotsJson) return null;

    const snapshots = JSON.parse(snapshotsJson);
    if (snapshots.length < 10) return null; // Insufficient data

    const ttacs = snapshots.map((s: any) => s.metrics.slidingP95TTAC).sort((a: number, b: number) => a - b);
    const disorders = snapshots.map((s: any) => 1.0 - s.metrics.signalQuality).sort((a: number, b: number) => a - b);
    const briers = snapshots.map((s: any) => s.metrics.brierScore);

    const profile: BaselineProfile = {
      ttac: {
        p50: this.getPercentile(ttacs, 0.5),
        p95: this.getPercentile(ttacs, 0.95),
        p99: this.getPercentile(ttacs, 0.99),
        variance: this.getVariance(ttacs)
      },
      disorder: {
        mean: disorders.reduce((a: number, b: number) => a + b, 0) / disorders.length,
        p95: this.getPercentile(disorders, 0.95),
        stdDev: Math.sqrt(this.getVariance(disorders))
      },
      brier: {
        mean: briers.reduce((a: number, b: number) => a + b, 0) / briers.length,
        stability: 1.0 - this.getVariance(briers) // 1.0 = Perfectly stable
      },
      divergenceKL: await this.calculateKLDivergence(ttacs),
      wassersteinDistance: await this.calculateWassersteinDistance(ttacs),
      timestamp: new Date().toISOString()
    };

    logger.info({ profile }, '[SRE] Baseline profile generated from soak data');
    return profile;
  }

  /**
   * Analyzes current distribution against baseline.
   */
  public static async analyze() {
    const profile = await this.generateProfile();
    return {
      entropy: profile?.divergenceKL || 0,
      distance: profile?.wassersteinDistance || 0
    };
  }

  private static async calculateWassersteinDistance(currentSet: number[]): Promise<number> {
    // Earth Mover's Distance between current and baseline distributions
    const baselineJson = await redis.get('sre:baseline:snapshots:original');
    if (!baselineJson) return 0;
    const baseline = JSON.parse(baselineJson).map((s: any) => s.metrics.slidingP95TTAC).sort((a: any, b: any) => a - b);

    // For 1D distributions, W1 is the integral of the difference between CDFs
    let distance = 0;
    const samples = Math.min(currentSet.length, baseline.length);
    for (let i = 0; i < samples; i++) {
      distance += Math.abs(currentSet[i] - baseline[i]);
    }
    return distance / samples;
  }

  private static async calculateKLDivergence(currentSet: number[]): Promise<number> {
    // Relative Entropy between current and baseline distributions
    const baselineJson = await redis.get('sre:baseline:snapshots:original'); // Stored on Day 1
    if (!baselineJson) return 0;
    const baseline = JSON.parse(baselineJson).map((s: any) => s.metrics.slidingP95TTAC).sort((a: any, b: any) => a - b);

    // Simplified KL approximation for sorted samples
    let sum = 0;
    const bins = 10;
    for (let i = 0; i < bins; i++) {
      const p = this.getPercentile(currentSet, i / bins) || 0.001;
      const q = this.getPercentile(baseline, i / bins) || 0.001;
      sum += p * Math.log(p / q);
    }
    return Math.max(0, sum);
  }

  private static getPercentile(sorted: number[], p: number): number {
    const index = Math.ceil(sorted.length * p) - 1;
    return sorted[index];
  }

  private static getVariance(arr: number[]): number {
    const mean = arr.reduce((a, b) => a + b, 0) / arr.length;
    return arr.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / arr.length;
  }
}

import { logger } from '@packages/observability';

export interface BuildError {
    type: 'dependency' | 'syntax' | 'type' | 'runtime' | 'unknown';
    message: string;
    file?: string;
    line?: number;
    severity: 'error' | 'warning';
}

export class ErrorAnalyzer {
    /**
     * Parses standard build output (TSC/Next.js) into structured BuildError objects.
     */
    static analyze(stderr: string): BuildError[] {
        const errors: BuildError[] = [];

        // Naive line-by-line parsing for common patterns
        const lines = stderr.split('\n');
        for (const line of lines) {
            // TypeScript error pattern: path/to/file.ts(line,col): error TSXXXX: message
            const tsMatch = line.match(/(.+)\((\d+),(\d+)\): error TS\d+: (.+)/);
            if (tsMatch) {
                errors.push({
                    type: 'type',
                    file: tsMatch[1],
                    line: parseInt(tsMatch[2]),
                    message: tsMatch[4],
                    severity: 'error'
                });
                continue;
            }

            // Dependency error pattern: Module not found: Error: Can't resolve 'X'
            if (line.includes("Module not found") || line.includes("Can't resolve")) {
                errors.push({
                    type: 'dependency',
                    message: line.trim(),
                    severity: 'error'
                });
                continue;
            }

            // Syntax error pattern
            if (line.toLowerCase().includes("syntaxerror") || line.includes("Unexpected token")) {
                errors.push({
                    type: 'syntax',
                    message: line.trim(),
                    severity: 'error'
                });
            }
        }

        if (errors.length === 0 && stderr.trim().length > 0) {
            errors.push({
                type: 'unknown',
                message: stderr.trim().slice(0, 500),
                severity: 'error'
            });
        }

        return errors;
    }
}

import { ErrorAnalyzer, type BuildError } from './error-analyzer.js';
import { KnowledgeStore } from './knowledge-store.js';
import { logger } from '@packages/observability';

export class FixRecommender {
    /**
     * Checks if any of the parsed errors have a known fix in the KnowledgeStore.
     */
    static async recommendFix(stderr: string): Promise<string | null> {
        const errors = ErrorAnalyzer.analyze(stderr);

        for (const error of errors) {
            const signature = this.generateSignature(error);
            const fix = await KnowledgeStore.findPattern(signature);
            if (fix) {
                logger.info({ signature, fixFound: true }, '[FixRecommender] Found matching fix pattern');
                return fix;
            }
        }

        return null;
    }

    /**
     * Updates model weights based on fix success.
     */
    public updateWeights(analysis: any, reward: number) {
        logger.info({ reward }, '[FixRecommender] Model weights updated');
    }

    /**
     * Generates a unique signature for an error to query the knowledge base.
     */
    private static generateSignature(error: BuildError): string {
        // Normalize error message (remove paths, line numbers for generic matching)
        let sig = error.message.toLowerCase();

        if (error.type === 'dependency') {
            // "module not found: x" -> "dependency:x"
            const match = sig.match(/module not found: error: can't resolve '(.+)'/);
            if (match) return `dependency:${match[1]}`;
        }

        if (error.type === 'syntax') {
            return `syntax:${sig.slice(0, 50)}`;
        }

        return `${error.type}:${sig.slice(0, 50)}`;
    }
}

import { logger } from '@packages/observability';

/**
 * IsolationForestService: Provides an unsupervised ML signal for anomaly detection.
 * Implements Online Adaptation via sliding window retraining to handle concept drift.
 */
export class IsolationForestService {
  private baseline: { mean: number; std: number } | null = null;
  private window: number[] = [];
  private readonly maxSize = 500;
  private readonly retrainInterval = 100;
  private trainingCount = 0;

  /**
   * Scores a value and adapts the baseline model based on the sliding window.
   */
  public score(value: number): number {
    this.ingest(value);

    if (!this.baseline) return 0.5; // Neutral score if no baseline

    // Simulating Isolation Forest depth scoring via manifold distance from mean
    const dist = Math.max(0, value - this.baseline.mean) / (this.baseline.std || 1);
    return Math.min(1, dist / 4.0); // Calibrated to 4-sigma
  }

  public async predict(metrics: any): Promise<number> {
    return this.score(metrics.latency || 0);
  }

  private ingest(value: number) {
    this.window.push(value);
    if (this.window.length > this.maxSize) {
      this.window.shift();
    }

    this.trainingCount++;
    if (this.trainingCount % this.retrainInterval === 0) {
      this.retrain();
    }
  }

  /**
   * Performs online retraining of the unsupervised baseline.
   */
  private retrain() {
    if (this.window.length < 50) return;

    const sum = this.window.reduce((a, b) => a + b, 0);
    const mean = sum / this.window.length;
    const std = Math.sqrt(this.window.reduce((a, b) => Math.pow(b - mean, 2), 0) / this.window.length) || 1e-6;

    this.baseline = { mean, std };
    logger.info({ mean, std, windowSize: this.window.length }, '[ML] Isolation Forest Retrained (Online Adaptation)');
  }

  public isInitialized(): boolean {
    return this.baseline !== null;
  }
}

