export class ThresholdPanelComponent {
  @Input() ceremonyActive = false;
  @Input() ceremonyStatus: string = 'INIT';
  @Input() participants: any[] = [];
  @Input() signed = false;
  @Input() adversarialResults: any[] = [];
  @Input() isSimulating = false;

  @Output() onInit = new EventEmitter<{ t: number, n: number }>();
  @Output() onSign = new EventEmitter<string[]>();
  @Output() onReset = new EventEmitter<void>();
  @Output() onRunAdversarial = new EventEmitter<void>();
  @Output() onCheckCompliance = new EventEmitter<void>();
  @Output() onAdvanceDkg = new EventEmitter<void>();

  t: number = 2;
  n: number = 3;
  selectedNodeIds: string[] = [];

  get quorumReached() {
    return this.selectedNodeIds.length >= this.t;
  }

  get signedSigners() {
    return this.participants.filter(p => p.status === 'SIGNED');
  }

  get quorumPercentage() {
    return Math.min(100, (this.selectedNodeIds.length / this.t) * 100);
  }

  initCeremony() {
    this.onInit.emit({ t: this.t, n: this.n });
  }

  toggleParticipant(nodeId: string) {
    const idx = this.selectedNodeIds.indexOf(nodeId);
    if (idx === -1) {
      this.selectedNodeIds.push(nodeId);
    } else {
      this.selectedNodeIds.splice(idx, 1);
    }
  }

  sign() {
    this.onSign.emit(this.selectedNodeIds);
  }

  reset() {
    this.selectedNodeIds = [];
    this.onReset.emit();
  }

  runAdversarial() {
    this.onRunAdversarial.emit();
  }

  checkCompliance() {
    this.onCheckCompliance.emit();
  }

  advanceDkg() {
    this.onAdvanceDkg.emit();
  }
}

import { Injectable } from '@angular/core';
import { Observable, map } from 'rxjs';
import { environment } from '../../../environments/environment';
import { ApiService } from './api.service';

export interface ScalingDecision {
  id: string;
  type: string;
  strategy: string;
  reason: string;
  roi: number | null;
  improvementPct: number | null;
  metrics: any;
  createdAt: string;
}

export interface IntelligenceState {
  activeStrategies: Record<string, number>;
  systemStatus: string;
  lastScalingEvent: ScalingDecision | null;
}

export interface ROIMetrics {
  optimizations: number;
  failureRate: number;
  estimatedSavings: number;
  efficiencyGain: number;
  devHoursSaved: number;
  profitability: number;
  // Beta Engagement Tracking
  activationRate: number; // % of users with > 3 missions
  avgTimeToFirstSuccess: number; // minutes
  churnRisk: number; // % of users inactive for > 48h
  engagementScore: number; // 0-100 based on usage depth
}

@Injectable({
  providedIn: 'root'
})
export class AdminService {
  private apiUrl = `/admin/intelligence`;

  constructor(private api: ApiService) {}

  getROIMetrics(tenantId?: string): Observable<ROIMetrics> {
    const url = tenantId ? `${this.apiUrl}/roi?tenantId=${tenantId}` : `${this.apiUrl}/roi`;
    return this.api.get<{ data: ROIMetrics }>(url).pipe(map(res => res.data));
  }

  getScalingTimeline(): Observable<ScalingDecision[]> {
    return this.api.get<{ data: ScalingDecision[] }>(`${this.apiUrl}/timeline`).pipe(map(res => res.data));
  }

  getIntelligenceState(): Observable<IntelligenceState> {
    return this.api.get<{ data: IntelligenceState }>(`${this.apiUrl}/state`).pipe(map(res => res.data));
