        },
        {
            timeout: 10000,
            errorThresholdPercentage: 50,
            resetTimeout: 30000,
        }
    );

    app.post('/api/checkout', express.json() as any, (async (req: Request, res: Response) => {
        try {
            const result = await stripeBreaker.fire(req.body);
            res.json(result);
        } catch (err) {
            logger.error({ err }, '[Gateway] Checkout Failed / Circuit Open');
            res.status(503).json({
