export const DEFAULT_THRESHOLD = 2;
export const DEFAULT_NODE_IDS = ['node-a', 'node-b', 'node-c'];

export interface KeyShare {
  nodeId: string;
  share: bigint;
  groupPublicKey: string;
  pop: string;
}

export interface PartialSignature {
  nodeId: string;
  signature: string;
