                expectedSaving: 0.25,
                urgency: 'HIGH',
                description: 'Governance metadata expansion is outpacing trust accumulation. Compressing active constitutional epochs is recommended.'
            });
        }

        // Check for compute entropy
        if (state.replayLatency > 500) {
            recommendations.push({
                id: 'OPT-003',
                action: 'ARCHIVE_AGED_EVIDENCE',
                targetPackage: 'evidence-lifecycle',
                expectedSaving: 0.10,
                urgency: 'LOW',
                description: 'Replay compute cost is rising due to evidence volume. Archiving evidence older than 2 governance epochs will stabilize compute latency.'
            });
        }

        if (recommendations.length > 0) {
            console.warn(`📉 Found ${recommendations.length} sustainability optimizations.`);
        }

        return recommendations;
    }

    /**
     * Assign a sustainability rating (A-F) based on efficiency and trend.
     */
    static calculateSustainabilityRating(efficiencyScore: number): string {
        if (efficiencyScore >= 0.95) return 'A+';
        if (efficiencyScore >= 0.90) return 'A';
        if (efficiencyScore >= 0.80) return 'B';
        if (efficiencyScore >= 0.70) return 'C';
        if (efficiencyScore >= 0.60) return 'D';
        return 'F';
    }
}

import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';

const NAMESPACE = 'ztan-validation';
const REPLAY_DIR = path.join('archive', 'recovery_replays');

if (!fs.existsSync(REPLAY_DIR)) {
    fs.mkdirSync(REPLAY_DIR, { recursive: true });
}

function logReplay(name: string, success: boolean, details: any) {
    const timestamp = new Date().toISOString();
    const replayId = `replay-${Date.now()}`;
    const dir = path.join(REPLAY_DIR, replayId);
    fs.mkdirSync(dir, { recursive: true });

    const metadata = {
        replayId,
        name,
        timestamp,
        success,
        details,
        envFingerprint: {
            os: process.platform,
            node: process.version
        }
    };

    fs.writeFileSync(path.join(dir, 'run_metadata.json'), JSON.stringify(metadata, null, 2));
    console.log(`[REPLAY] Recorded ${name} (${success ? 'SUCCESS' : 'FAILED'}): ${replayId}`);
}

async function runValidation() {
    console.log('🚀 Nexus ZTAN Real-Time Operational Validation');

    // 1. Successful Rollout
    console.log('\n[MUTATION-01] Executing successful rollout...');
    try {
        execSync(`kubectl set env deployment/api VALIDATION_VERSION=v1.1 -n ${NAMESPACE}`);
        execSync(`kubectl rollout status deployment/api -n ${NAMESPACE} --timeout=60s`);
        logReplay('successful_rollout', true, { version: 'v1.1' });
    } catch (e) {
        logReplay('successful_rollout', false, { error: e.message });
    }

    // 2. Failed Rollout
    console.log('\n[MUTATION-02] Executing failed rollout (invalid image)...');
    try {
        execSync(`kubectl set image deployment/api api=nonexistent-image:latest -n ${NAMESPACE}`);
        // We expect this to hang/fail or we wait and see ErrImagePull
        console.log('Waiting for failure detection...');
        setTimeout(() => {
            const pods = execSync(`kubectl get pods -n ${NAMESPACE} -l app=api`).toString();
            const isFailed = pods.includes('ErrImagePull') || pods.includes('ImagePullBackOff');
            logReplay('failed_rollout_injection', isFailed, { pods });

            // 3. Rollback
            console.log('\n[MUTATION-03] Executing rollback...');
            try {
                execSync(`kubectl rollout undo deployment/api -n ${NAMESPACE}`);
                execSync(`kubectl rollout status deployment/api -n ${NAMESPACE} --timeout=60s`);
                logReplay('rollback_execution', true, { status: 'restored' });
            } catch (re) {
                logReplay('rollback_execution', false, { error: re.message });
            }
        }, 15000);
    } catch (e) {
        logReplay('failed_rollout_injection', false, { error: e.message });
    }
}

