                            response = `BLOCKED: Digest substitution rejected. Message: ${err.message}`;
                        } else {
                            isSecure = false;
                            response = `FAILED: Verification threw unexpected error: ${err.message}`;
                        }
                    }
                }
            } catch (err: any) {
                isSecure = false;
                response = `EXHAUSTED (Crash): ${err.message}`;
            }

            if (isSecure) {
                secure++;
            } else {
                vulnerable++;
            }

            results.push({
                test,
                secure: isSecure,
                response
            });
        }

        return {
            total: tests.length,
            secure,
            vulnerable,
            results
        };
    }
}

