export enum MembershipState {
    JOINING = 'JOINING',
    ACTIVE = 'ACTIVE',
    SUSPECT = 'SUSPECT',
    DEGRADED = 'DEGRADED',
    DISCONNECTED = 'DISCONNECTED',
    FENCED = 'FENCED'
