                        workflowId: this.workflowId,
                        timestamp: Date.now(),
                        payload: { taskId, result: res }
                    });
                    ztanTaskQueueDepth.dec({ workflow_id: this.workflowId });
                    span.setStatus({ code: 1 });
                    span.end();
                    resolve(res);
