                        workflowId: this.workflowId,
                        timestamp: Date.now(),
                        payload: { taskId, error: err.message }
                    });
                    ztanTaskQueueDepth.dec({ workflow_id: this.workflowId });
                    span.setStatus({ code: 2, message: err.message });
                    span.recordException(err);
                    span.end();
                    reject(err);
                }
            });
        });
    }
