            const hashVal = this.hash(virtualKey);
            this.ring.delete(hashVal);
        }
        this.rebuildSortedKeys();
    }

    private rebuildSortedKeys(): void {
        this.sortedKeys = Array.from(this.ring.keys()).sort((a, b) => a - b);
