export interface TlsConfig {
    cert: string;
    key: string;
    ca?: string;
    rejectUnauthorized?: boolean;
    requestCert?: boolean;
}

export interface TcpPeerConfig {
    nodeId: string;
    host: string;
    port: number;
}

interface PendingRequest {
    resolve: (val: any) => void;
    reject: (err: any) => void;
