     */
    public static virtualizeTimers(scheduler: DeterministicScheduler): void {
        const virtualSetTimeout = (callback: (...args: any[]) => void, delay?: number, ...args: any[]): any => {
            const taskId = scheduler.schedule(`timer-delay-${delay || 0}`, async () => {
                callback(...args);
