            'JWT_SECRET',
            'LOG_LEVEL'
        ]);
        const envSnapshot = captureEnvironmentSnapshot(coreZtanVars);

        // 2. Export Recent WAL & Ledger Sequences
        const sequenceSnapshot = await exportRecentSequences(this.prisma, 10);

        // 3. Classify Quarantine Cause
