// ─── Witness Member ─────────────────────────────────────────────────────────

export interface WitnessStateEntry {
    member: WitnessMember;
    status: 'ACTIVE' | 'REMOVED' | 'QUARANTINED';
    addedAt: string;
    removedAt?: string;
