const execAsync = promisify(exec);
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, '..');
dotenv.config({ path: path.join(rootDir, '.env') });

/**
 * ZTAN STATEFUL RESOURCE EXHAUSTION ARCHAEOLOGY RUNNER
 * 
 * Conducts targeted physical stressors to capture non-binary systems degradation curves:
 * 1. File Descriptor Churn
 * 2. Libuv Threadpool Starvation
 * 3. Connection Pool Saturation
 * 4. TCP TIME_WAIT Sockets Accumulation
 * 5. Write Latency & WAL Amplification Slopes
 */

async function querySocketsCount(): Promise<number> {
  try {
    const { stdout } = await execAsync(`netstat -ano`);
    const rows = stdout.split(/\r?\n/);
    let timeWait = 0;
    for (const row of rows) {
      if (row.includes('TIME_WAIT')) {
        timeWait++;
      }
    }
    return timeWait;
  } catch {
    return 0;
  }
}

async function main() {
  console.log('================================================================');
  console.log('🏗️  INITIATING STATEFUL RESOURCE EXHAUSTION ARCHAEOLOGY');
  console.log('================================================================');

  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.error('❌ ERROR: DATABASE_URL is not set in .env.');
    process.exit(1);
  }

  const prisma = new PrismaClient({ datasources: { db: { url: dbUrl } } });
  let initialBackup: ZtanDbBackup | null = null;

  const curves: {
    fileDescriptors: Array<{ step: number; openHandles: number }>;
    threadpoolStarvation: Array<{ task: number; timeMs: number }>;
    connectionPool: Array<{ conn: number; acquisitionMs: number }>;
    socketTimeWait: Array<{ tick: number; timeWaitCount: number }>;
    walAmplification: Array<{ sizeKb: number; durationMs: number }>;
  } = {
    fileDescriptors: [],
    threadpoolStarvation: [],
    connectionPool: [],
    socketTimeWait: [],
    walAmplification: []
  };

  try {
    // -------------------------------------------------------------------------
    // Phase 1: Database State Safeguard
    // -------------------------------------------------------------------------
    console.log('\n🔐 PHASE 1: Database State Safeguard');
    initialBackup = await backupDatabaseState(dbUrl);
    console.log('   ✅ Pre-mutation database snapshot successfully stored.');

    // -------------------------------------------------------------------------
    // Stressor 1: File Descriptor / Handles Churn
    // -------------------------------------------------------------------------
    console.log('\n📂 STRESSOR 1: File Descriptor & File Handles Churn');
    const tempDir = path.join(rootDir, 'scratch', 'fd_leak_test');
    if (!fs.existsSync(tempDir)) {
      fs.mkdirSync(tempDir, { recursive: true });
    }

    const fileHandles: fs.promises.FileHandle[] = [];
    console.log('   - Opening 150 file descriptors concurrently to trace OS handle slope...');
    for (let i = 0; i < 150; i++) {
      const filePath = path.join(tempDir, `fd_${i}.log`);
      const fh = await fs.promises.open(filePath, 'w+');
      fileHandles.push(fh);
      if (i % 25 === 0) {
        curves.fileDescriptors.push({ step: i, openHandles: fileHandles.length });
        console.log(`      - Open handles count: ${fileHandles.length}`);
      }
    }
    console.log(`   ✅ Handle slope verified. Open file descriptors = ${fileHandles.length}`);

    // Clean up file handles
    for (const fh of fileHandles) {
      await fh.close();
    }
    try {
      fs.rmSync(tempDir, { recursive: true, force: true });
    } catch {}

    // -------------------------------------------------------------------------
    // Stressor 2: Libuv Threadpool Starvation
    // -------------------------------------------------------------------------
    console.log('\n⚡ STRESSOR 2: Libuv Threadpool Saturation & Task Starvation');
    console.log('   - Saturating threadpool with concurrent heavy cryptographic hashes...');

    // We schedule a non-blocking asynchronous file read to measure thread pool delay
    const testFile = path.join(rootDir, 'package.json');
    const measureFileRead = async (taskIndex: number) => {
      const start = performance.now();
      await fs.promises.readFile(testFile, 'utf8');
      const timeMs = performance.now() - start;
      curves.threadpoolStarvation.push({ task: taskIndex, timeMs });
    };

    // Burn thread pool with pbkdf2Sync tasks executing in parallel
    const crytoPromises: Promise<any>[] = [];
    const readPromises: Promise<any>[] = [];

    for (let i = 0; i < 8; i++) {
      // Schedule background reads
      readPromises.push(measureFileRead(i));
      // Schedule cpu block
      crytoPromises.push(new Promise((resolve) => {
        setImmediate(() => {
          const pass = crypto.randomBytes(16).toString('hex');
          const salt = crypto.randomBytes(16).toString('hex');
          crypto.pbkdf2Sync(pass, salt, 100000, 64, 'sha512');
          resolve(true);
        });
      }));
    }

    await Promise.all([...readPromises, ...crytoPromises]);
    console.log(`   ✅ Starvation curve captured. Worst-case task read latency: ${Math.max(...curves.threadpoolStarvation.map(c => c.timeMs)).toFixed(2)} ms`);

    // -------------------------------------------------------------------------
    // Stressor 3: Prisma Database Connection Pool Saturation
    // -------------------------------------------------------------------------
    console.log('\n🗄️  STRESSOR 3: Prisma DB Connection Pool Saturation');
    console.log('   - Occupying connections with concurrent locking pg_sleep transactions...');

    const poolAcquisitionPromises: Promise<any>[] = [];
    for (let i = 0; i < 8; i++) {
      poolAcquisitionPromises.push((async () => {
        const start = performance.now();
        try {
          // Attempt query
          await prisma.$executeRawUnsafe(`SELECT pg_sleep(0.1);`);
          const acquisitionMs = performance.now() - start;
          curves.connectionPool.push({ conn: i, acquisitionMs });
        } catch (e: any) {
          console.warn(`      - Connection pool caught connection error: ${e.message}`);
        }
      })());
    }

    await Promise.all(poolAcquisitionPromises);
    console.log(`   ✅ Pool saturation metrics captured. Peak acquisition time: ${Math.max(...curves.connectionPool.map(c => c.acquisitionMs)).toFixed(2)} ms`);

    // -------------------------------------------------------------------------
    // Stressor 4: TCP TIME_WAIT Port Accumulation
    // -------------------------------------------------------------------------
    console.log('\n🔌 STRESSOR 4: TCP TIME_WAIT Socket Port Accumulation');

    const timeWaitBefore = await querySocketsCount();
    console.log(`   - TCP TIME_WAIT sockets before connection storm: ${timeWaitBefore}`);

    // Simulate connection storm by triggering rapid micro TCP connections
    const stormPromises: Promise<any>[] = [];
    const server = net.createServer((socket) => {
      socket.end();
    }).listen(4088, '127.0.0.1');

    const triggerTcpRequest = () => {
      return new Promise((resolve) => {
        const socket = net.createConnection({ host: '127.0.0.1', port: 4088 }, () => {
          socket.end();
        });
        socket.on('close', () => resolve(true));
        socket.on('error', () => resolve(false));
      });
    };

    for (let i = 0; i < 50; i++) {
      stormPromises.push(triggerTcpRequest());
    }
    await Promise.all(stormPromises);
    server.close();

    const timeWaitAfter = await querySocketsCount();
    console.log(`   - TCP TIME_WAIT sockets after connection storm: ${timeWaitAfter}`);
    curves.socketTimeWait.push({ tick: 0, timeWaitCount: timeWaitBefore });
    curves.socketTimeWait.push({ tick: 1, timeWaitCount: timeWaitAfter });

    // -------------------------------------------------------------------------
    // Stressor 5: WAL Amplification & Write Latency Slopes
    // -------------------------------------------------------------------------
    console.log('\n📝 STRESSOR 5: WAL Amplification & Write Latency Slopes');
    await prisma.$executeRawUnsafe(`TRUNCATE TABLE "ZtanLedgerBlock" RESTART IDENTITY CASCADE;`);

    const sizes = [1, 10, 50, 100]; // KB sizes
    for (const size of sizes) {
      const payload = 'x'.repeat(size * 1024);
      const start = performance.now();
      await prisma.ztanLedgerBlock.create({
        data: {
          blockId: `wal-block-${size}`,
          prevHash: 'GENESIS_PREV_HASH',
          hash: `hash-wal-${size}`,
          type: 'TX_BATCH',
          payload: payload,
          operator: 'ZTAN_STRESSOR',
          signature: 'sig',
          status: 'VERIFIED',
          epoch: '1'
        }
      });
      const durationMs = performance.now() - start;
      curves.walAmplification.push({ sizeKb: size, durationMs });
      console.log(`      - Payload size: ${size} KB, write execution delay: ${durationMs.toFixed(2)} ms`);
    }

    // Save final downsampled archaeology datasets to JSON
    const snapshotPath = path.join(rootDir, 'telemetry-history', 'resource_archaeology_latest.json');
    fs.writeFileSync(snapshotPath, JSON.stringify({
      timestamp: Date.now(),
      curves
    }, null, 2), 'utf-8');
    console.log('\n   ✅ SRE degradation curves successfully recorded to telemetry-history/resource_archaeology_latest.json');

  } catch (err: any) {
    console.error(`\n❌ ERROR: Resource exhaustion archaeology failed: ${err.message}`);
    process.exit(1);
  } finally {
    // -------------------------------------------------------------------------
    // State restoration & cleanup
    // -------------------------------------------------------------------------
    console.log('\n🏗️  PHASE 6: Database State Restoration & Clean Teardown');
    if (initialBackup) {
      try {
        await restoreDatabaseState(initialBackup, dbUrl);
        console.log('   ✅ Pre-mutation database state fully restored. Clean-room verification secure.');
      } catch (restoreErr: any) {
        console.error(`   ❌ CRITICAL: Failed to restore initial database state: ${restoreErr.message}`);
      }
    }
    await prisma.$disconnect();
  }

  console.log('\n================================================================');
  console.log('🏁 DRILL VERDICT: PASSED ✅');
  console.log('   Degradation curves fully mapped under stateful physical resource limits.');
  console.log('================================================================');
}

main().catch(err => {
  console.error(`❌ Crash in main: ${err.message}`);
  process.exit(1);
});

import { spawn, execSync } from 'child_process';
import axios from 'axios';
import path from 'path';
import fs from 'fs';

const lockfilePath = path.join(process.cwd(), '.ztan-orchestrator-pids.json');

async function wait(ms: number) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

async function main() {
    console.log('\n╔══════════════════════════════════════════════════════════╗');
    console.log('║        ZTAN RESILIENCE & CHAOS VALIDATION CAMPAIGN       ║');
    console.log('╚══════════════════════════════════════════════════════════╝\n');

    // 1. Spawning Orchestrator
    console.log('🚀 Spawning microservice development orchestrator...');
    const orchProc = spawn('npx', ['tsx', 'scripts/start-dev.ts'], {
        cwd: process.cwd(),
        stdio: 'pipe',
        shell: true
    });

    let combinedOutput = '';
    orchProc.stdout.on('data', (data) => {
        const str = data.toString();
        combinedOutput += str;
        process.stdout.write(str);
    });

    orchProc.stderr.on('data', (data) => {
        const str = data.toString();
        combinedOutput += str;
        process.stderr.write(str);
    });

    // Wait for system to become fully operational
    console.log('⏳ Waiting for all services to become operational...');
    let stabilized = false;
    for (let i = 0; i < 120; i++) {
        if (combinedOutput.includes('ALL SERVICES OPERATIONAL')) {
            stabilized = true;
            break;
        }
        await wait(2000);
    }

    if (!stabilized) {
        console.error('❌ Orchestrator failed to stabilize in 240s. Aborting campaign.');
        cleanup(orchProc);
        process.exit(1);
    }

    console.log('\n✅ System stabilized. Commencing chaos injection scenarios...\n');

    // ─── Scenario 1: Event-Loop Lag & Backpressure Admission Control ───
    console.log('🛡️  [Scenario 1] Testing Gateway Event-Loop Lag Admission Control...');
    
    // Normal request
    try {
        const resNormal = await axios.get('http://127.0.0.1:3500/', {
            headers: { 'x-priority': 'low' }
        });
        console.log(`  - Normal request: HTTP ${resNormal.status} (Expected: 200)`);
    } catch (e: any) {
        console.error(`  - Normal request failed:`, e.message);
    }

    // Inject simulated lag of 300ms
    console.log('  - Injecting simulated Gateway event loop lag of 300ms...');
    try {
        await axios.post('http://127.0.0.1:3500/api/v1/chaos/lag', { durationMs: 300 });
    } catch (e: any) {
        console.error(`  - Failed to inject chaos lag:`, e.message);
    }

    // Verify low priority is shed
    await wait(200);
    console.log('  - Verifying low-priority traffic is shed (HTTP 429)...');
    let lowShed = false;
    try {
        await axios.get('http://127.0.0.1:3500/', {
            headers: { 'x-priority': 'low' }
        });
    } catch (e: any) {
        if (e.response && e.response.status === 429) {
            lowShed = true;
            console.log(`  ✅ Low-priority request correctly shed: HTTP 429 (${e.response.data.error})`);
        } else {
            console.error(`  - Unexpected low-priority response:`, e.message);
        }
    }

    // Clear simulated lag
    console.log('  - Clearing simulated lag...');
    try {
        await axios.post('http://127.0.0.1:3500/api/v1/chaos/lag', { durationMs: 0 });
    } catch (e: any) {}

    // Verify critical priority bypasses shed policy
    console.log('  - Verifying critical-priority traffic bypasses shedding...');
    let criticalBypass = false;
    try {
        const resCritical = await axios.get('http://127.0.0.1:3500/', {
            headers: { 'x-priority': 'critical' }
        });
        if (resCritical.status === 200) {
            criticalBypass = true;
            console.log(`  ✅ Critical-priority request correctly bypassed shedding: HTTP 200`);
        }
    } catch (e: any) {
        console.error(`  - Critical-priority request failed:`, e.message);
    }

    // ─── Scenario 2: Dependency-Aware Suppression ───
    console.log('\n🔗 [Scenario 2] Testing Dependency-Aware Restart Suppression...');

    // Load active PIDs from lockfile
    if (!fs.existsSync(lockfilePath)) {
        console.error('❌ Lockfile .ztan-orchestrator-pids.json not found!');
        cleanup(orchProc);
        process.exit(1);
    }

    const pids = JSON.parse(fs.readFileSync(lockfilePath, 'utf8')) as { name: string; pid: number }[];
    const coreApiObj = pids.find(p => p.name === 'Core API');
    const authServiceObj = pids.find(p => p.name === 'Auth Service');

    if (!coreApiObj || !authServiceObj) {
        console.error('❌ Active Core API or Auth Service PIDs not found in lockfile!');
        cleanup(orchProc);
        process.exit(1);
    }

    console.log(`  - Active Core API PID: ${coreApiObj.pid}`);
    console.log(`  - Active Auth Service PID: ${authServiceObj.pid}`);

    // Kill Core API first (upstream dependency)
    console.log(`  - Killing upstream dependency (Core API PID ${coreApiObj.pid})...`);
    try {
        if (process.platform === 'win32') {
            execSync(`taskkill /F /PID ${coreApiObj.pid}`, { stdio: 'ignore' });
        } else {
            process.kill(coreApiObj.pid, 'SIGKILL');
        }
    } catch (e) {}

    // Kill Auth Service immediately (downstream service)
    console.log(`  - Killing downstream service (Auth Service PID ${authServiceObj.pid})...`);
    try {
        if (process.platform === 'win32') {
            execSync(`taskkill /F /PID ${authServiceObj.pid}`, { stdio: 'ignore' });
        } else {
            process.kill(authServiceObj.pid, 'SIGKILL');
        }
    } catch (e) {}

    // Monitor stdout to ensure restart of Auth Service is suppressed
    console.log('  - Monitoring suppression logs...');
    let suppressionLogged = false;
    for (let i = 0; i < 20; i++) {
        if (combinedOutput.includes('Suppression: Delaying restart of Auth Service because its dependency Core API is currently down')) {
            suppressionLogged = true;
            break;
        }
        await wait(1000);
    }

    if (suppressionLogged) {
        console.log(`  ✅ Restart suppression verified: Downstream Auth Service recovery paused while Core API was down.`);
    } else {
        console.error(`  ❌ Restart suppression was NOT logged!`);
    }

    // ─── Scorecard ───
    console.log('\n╔══════════════════════════════════════════════════════════╗');
    console.log('║                   CHAOS CAMPAIGN SCORECARD               ║');
    console.log('╠══════════════════════════════════════════════════════════╣');
    console.log(`║  🛡️  Gateway Load Shedding (HTTP 429)      ${lowShed ? 'PASS ✅' : 'FAIL ❌'}  ║`);
    console.log(`║  🛡️  Priority Bypass (x-priority)          ${criticalBypass ? 'PASS ✅' : 'FAIL ❌'}  ║`);
    console.log(`║  🔗 Dependency Restart Suppression         ${suppressionLogged ? 'PASS ✅' : 'FAIL ❌'}  ║`);
    
    const allPassed = lowShed && criticalBypass && suppressionLogged;
    console.log('╠══════════════════════════════════════════════════════════╣');
    console.log(`║  Campaign Result: ${allPassed ? 'RESILIENT 🟢' : 'ISSUES DETECTED 🔴'}                     ║`);
    console.log('╚══════════════════════════════════════════════════════════╝\n');

    cleanup(orchProc);
    process.exit(allPassed ? 0 : 1);
}

function cleanup(proc: any) {
    console.log('🛑 Cleaning up all test processes...');
    try {
        if (process.platform === 'win32') {
            execSync(`taskkill /F /T /PID ${proc.pid}`, { stdio: 'ignore' });
        } else {
            proc.kill('SIGKILL');
        }
    } catch (e) {}
    
    // Read and kill remaining lockfile processes
    try {
        if (fs.existsSync(lockfilePath)) {
            const pids = JSON.parse(fs.readFileSync(lockfilePath, 'utf8')) as { name: string; pid: number }[];
            for (const item of pids) {
                try {
                    if (process.platform === 'win32') {
                        execSync(`taskkill /F /T /PID ${item.pid}`, { stdio: 'ignore' });
                    } else {
                        process.kill(item.pid, 'SIGKILL');
                    }
                } catch (e) {}
            }
            fs.unlinkSync(lockfilePath);
        }
    } catch (e) {}
}

main().catch(err => {
    console.error('Fatal campaign execution error:', err);
    process.exit(1);
});

import { execSync } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';
import dotenv from 'dotenv';
import dotenvExpand from 'dotenv-expand';

const envConfig = dotenv.config();
dotenvExpand.expand(envConfig);

const TELEMETRY_DIR = path.join(process.cwd(), '.planning', 'telemetry');
const TRANSPARENCY_DIR = path.join(process.cwd(), 'packages', 'utils', 'src', 'transparency');

const DRILLS = [
  'test-lease-fencing.ts',
  'test-failure-semantics.ts',
  'test-outbox-self-healing.ts',
  'test-outbox-resilience.ts',
  'test-ledger-compaction.ts',
  'test-multi-writer.ts',
  'test-byzantine-drift.ts',
  'test-hsm-ceremony.ts',
  'test-replicated-consensus.ts'
];

interface DrillResult {
  name: string;
  success: boolean;
  durationMs: number;
  error?: string;
}

async function runAllDrills() {
  console.log("=========================================================================");
  console.log("🚀 STARTING ZTAN PHASE E POSTGRES FAILOVER & LEASE CHAOS DRILLS");
  console.log("=========================================================================");

  if (!fs.existsSync(TELEMETRY_DIR)) {
    fs.mkdirSync(TELEMETRY_DIR, { recursive: true });
  }

  const results: DrillResult[] = [];
  let successCount = 0;
  let failureCount = 0;

  for (const drill of DRILLS) {
    const drillPath = path.join(TRANSPARENCY_DIR, drill);
    console.log(`\n[DRILL] Running ${drill}...`);
    const start = Date.now();

    try {
      execSync(`npx tsx "${drillPath}"`, {
        env: { ...process.env, ZTAN_PARTITIONS: '1' },
        stdio: 'inherit'
      });
      const durationMs = Date.now() - start;
      console.log(`✅ [SUCCESS] ${drill} passed in ${durationMs}ms`);
      results.push({ name: drill, success: true, durationMs });
      successCount++;
    } catch (err: any) {
      const durationMs = Date.now() - start;
      console.error(`❌ [FAILURE] ${drill} failed after ${durationMs}ms`);
      results.push({
        name: drill,
        success: false,
        durationMs,
        error: err.message || String(err)
      });
      failureCount++;
    }
  }

  const timestamp = new Date().toISOString();
  const summaryReport = {
    timestamp,
    successCount,
    failureCount,
    totalCount: DRILLS.length,
    results
  };

  const filename = `drill-results-${Date.now()}.json`;
  const reportPath = path.join(TELEMETRY_DIR, filename);
  fs.writeFileSync(reportPath, JSON.stringify(summaryReport, null, 2), 'utf8');

  console.log("\n=========================================================================");
  console.log(`📊 CHAOS DRILL EXECUTION COMPLETED at ${timestamp}`);
  console.log(`   Success: ${successCount} / ${DRILLS.length}`);
  console.log(`   Failure: ${failureCount} / ${DRILLS.length}`);
  console.log(`   Report saved to: ${reportPath}`);
  console.log("=========================================================================");

  if (failureCount > 0) {
    process.exit(1);
  } else {
    process.exit(0);
  }
}

runAllDrills().catch((err) => {
  console.error("Fatal error executing Phase E drills:", err);
  process.exit(1);
});

