<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>ZTAN Bounded Operational Observatory</title>
    <link href="https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;600;700&family=JetBrains+Mono&display=swap" rel="stylesheet">
    <style>
        :root {
            --bg-dark: #0b0f19;
            --card-glass: rgba(17, 24, 39, 0.7);
            --border-glass: rgba(255, 255, 255, 0.08);
            --primary-accent: #6366f1;
            --accent-glow: rgba(99, 102, 241, 0.15);
            --success-color: #10b981;
            --warning-color: #f59e0b;
            --error-color: #ef4444;
            --text-main: #f3f4f6;
            --text-secondary: #9ca3af;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: 'Outfit', sans-serif;
            background-color: var(--bg-dark);
            color: var(--text-main);
            overflow-x: hidden;
            background-image: 
                radial-gradient(circle at 10% 20%, rgba(99, 102, 241, 0.08) 0%, transparent 40%),
                radial-gradient(circle at 90% 80%, rgba(16, 185, 129, 0.05) 0%, transparent 40%);
            min-height: 100vh;
        }

        header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 24px 48px;
            backdrop-filter: blur(12px);
            border-bottom: 1px solid var(--border-glass);
            background: rgba(11, 15, 25, 0.6);
            position: sticky;
            top: 0;
            z-index: 100;
        }

        .logo-container {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .logo-container h1 {
            font-size: 24px;
            font-weight: 700;
            letter-spacing: 1.5px;
            background: linear-gradient(135deg, #a5b4fc, #818cf8);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .logo-badge {
            background: rgba(99, 102, 241, 0.2);
            color: var(--primary-accent);
            padding: 4px 8px;
            border-radius: 6px;
            font-size: 11px;
            font-weight: 700;
            border: 1px solid rgba(99, 102, 241, 0.3);
        }

        .status-container {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .status-dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background-color: var(--success-color);
            box-shadow: 0 0 12px var(--success-color);
            animation: pulse 2s infinite;
        }

        @keyframes pulse {
            0% { transform: scale(1); opacity: 1; }
            50% { transform: scale(1.2); opacity: 0.7; }
            100% { transform: scale(1); opacity: 1; }
        }

        .main-layout {
            display: grid;
            grid-template-columns: 1.2fr 1fr;
            gap: 32px;
            padding: 40px 48px;
            max-width: 1600px;
            margin: 0 auto;
        }

        .card {
            background: var(--card-glass);
            border: 1px solid var(--border-glass);
            border-radius: 16px;
            padding: 32px;
            backdrop-filter: blur(16px);
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
            margin-bottom: 32px;
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .card:hover {
            border-color: rgba(99, 102, 241, 0.25);
            box-shadow: 0 12px 40px rgba(99, 102, 241, 0.05);
        }

        .card-title {
            font-size: 18px;
            font-weight: 600;
            margin-bottom: 24px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-left: 4px solid var(--primary-accent);
            padding-left: 12px;
        }

        /* Interactive State Transition DAG */
        .dag-viewport {
            display: flex;
            justify-content: space-between;
            align-items: center;
            position: relative;
            background: rgba(0, 0, 0, 0.2);
            padding: 40px 24px;
            border-radius: 12px;
            border: 1px dashed var(--border-glass);
            margin-bottom: 24px;
        }

        .dag-node {
            background: rgba(17, 24, 39, 0.9);
            border: 2px solid var(--border-glass);
            padding: 16px 20px;
            border-radius: 12px;
            text-align: center;
            min-width: 120px;
            cursor: pointer;
            z-index: 10;
            position: relative;
            transition: all 0.3s ease;
        }

        .dag-node:hover {
            transform: translateY(-4px);
        }

        .dag-node.active-state {
            border-color: var(--success-color);
            background: rgba(16, 185, 129, 0.05);
            box-shadow: 0 0 20px rgba(16, 185, 129, 0.15);
        }

        .dag-node.quarantined-state {
            border-color: var(--error-color);
            background: rgba(239, 68, 68, 0.05);
            box-shadow: 0 0 20px rgba(239, 68, 68, 0.15);
        }

        .dag-node.readonly-state {
            border-color: var(--warning-color);
            background: rgba(245, 158, 11, 0.05);
        }

        .dag-node h4 {
            font-size: 14px;
            font-weight: 700;
            margin-bottom: 4px;
            letter-spacing: 0.5px;
        }

        .dag-node span {
            font-size: 10px;
            color: var(--text-secondary);
        }

        .dag-link {
            flex-grow: 1;
            height: 2px;
            background: var(--border-glass);
            position: relative;
            z-index: 1;
        }

        .dag-link::after {
            content: '➔';
            position: absolute;
            right: 0;
            top: -9px;
            color: var(--text-secondary);
            font-size: 12px;
        }

        /* Details Inspector Panel */
        .inspector-panel {
            background: rgba(17, 24, 39, 0.4);
            border-radius: 8px;
            padding: 16px;
            border: 1px solid var(--border-glass);
            font-size: 13px;
        }

        .inspector-title {
            font-weight: 600;
            color: var(--primary-accent);
            margin-bottom: 8px;
        }

        /* Form styling */
        .form-group {
            margin-bottom: 20px;
        }

        label {
            display: block;
            font-size: 12px;
            font-weight: 600;
            color: var(--text-secondary);
            margin-bottom: 8px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        input, textarea, select {
            width: 100%;
            background: rgba(0, 0, 0, 0.3);
            border: 1px solid var(--border-glass);
            padding: 12px 16px;
            border-radius: 8px;
            color: var(--text-main);
            font-family: inherit;
            font-size: 14px;
            transition: all 0.3s ease;
        }

        input:focus, textarea:focus, select:focus {
            outline: none;
            border-color: var(--primary-accent);
            box-shadow: 0 0 8px var(--accent-glow);
        }

        button {
            background: linear-gradient(135deg, #6366f1, #4f46e5);
            color: white;
            font-weight: 600;
            padding: 14px 28px;
            border: none;
            border-radius: 8px;
            cursor: pointer;
            width: 100%;
            transition: all 0.3s ease;
            font-family: inherit;
            letter-spacing: 0.5px;
        }

        button:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 20px var(--accent-glow);
        }

        /* WAL Diff logs */
        .log-table {
            width: 100%;
            border-collapse: collapse;
            font-family: 'JetBrains Mono', monospace;
            font-size: 12px;
        }

        .log-table th {
            text-align: left;
            padding: 12px 16px;
            color: var(--text-secondary);
            border-bottom: 1px solid var(--border-glass);
            font-weight: 600;
        }

        .log-table td {
            padding: 14px 16px;
            border-bottom: 1px solid var(--border-glass);
        }

        .log-row:hover {
            background: rgba(255, 255, 255, 0.02);
        }

        .status-badge {
            padding: 2px 6px;
            border-radius: 4px;
            font-size: 10px;
            font-weight: 700;
        }

        .status-badge.committed {
            background: rgba(16, 185, 129, 0.15);
            color: var(--success-color);
        }

        .status-badge.pending {
            background: rgba(245, 158, 11, 0.15);
            color: var(--warning-color);
        }

        /* Incident Guides */
        .guides-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 16px;
        }

        .guide-card {
            background: rgba(0, 0, 0, 0.2);
            border: 1px solid var(--border-glass);
            border-radius: 8px;
            padding: 16px;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .guide-card:hover {
            border-color: var(--primary-accent);
            background: rgba(99, 102, 241, 0.03);
        }

        .guide-card h5 {
            font-size: 14px;
            font-weight: 600;
            color: var(--primary-accent);
            margin-bottom: 6px;
        }

        .guide-card p {
            font-size: 11px;
            color: var(--text-secondary);
        }
    </style>
</head>
<body>
    <header>
        <div class="logo-container">
            <h1>ZTAN OPERATIONAL OBSERVATORY</h1>
            <span class="logo-badge">TIER P3</span>
        </div>
        <div class="status-container">
            <div class="status-dot" id="system-dot"></div>
            <span id="system-state-text" style="font-weight:600;">ACTIVE STATE</span>
        </div>
    </header>

    <main class="main-layout">
        <!-- Left column -->
        <div>
            <!-- Transition DAG -->
            <div class="card">
                <div class="card-title">Interactive State Transition DAG</div>
                <div class="dag-viewport">
                    <div class="dag-node active-state" id="node-active" onclick="inspectState('ACTIVE')">
                        <h4>ACTIVE</h4>
                        <span>Read/Write Active</span>
                    </div>
                    <div class="dag-link"></div>
                    <div class="dag-node readonly-state" id="node-readonly" onclick="inspectState('READ_ONLY')">
                        <h4>READ_ONLY</h4>
                        <span>Degraded/Advisory</span>
                    </div>
                    <div class="dag-link"></div>
                    <div class="dag-node" id="node-quarantined" onclick="inspectState('QUARANTINED')">
                        <h4>QUARANTINED</h4>
                        <span>Lockdown Active</span>
                    </div>
                </div>
                <div class="inspector-panel">
                    <div class="inspector-title" id="inspector-title">ACTIVE State Active Invariants</div>
                    <p id="inspector-desc">Single-writer active lease ownership validated. Full write path enabled. PostgreSQL PL/pgSQL fencing, append-only, and outbox Merkle chaining actively enforced. Epoch alignment is matching active lease generation terms.</p>
                </div>
            </div>

            <!-- WAL Replay Diff Viewer -->
            <div class="card">
                <div class="card-title">WAL Sequence Replay Diff Viewer</div>
                <div style="overflow-x: auto;">
                    <table class="log-table">
                        <thead>
                            <tr>
                                <th>SEQ</th>
                                <th>EVENT TYPE</th>
                                <th>PAYLOAD</th>
                                <th>STATUS</th>
                            </tr>
                        </thead>
                        <tbody id="wal-log-body">
                            <!-- Populated dynamically -->
                        </tbody>
                    </table>
                </div>
            </div>
        </div>

        <!-- Right column -->
        <div>
            <!-- Quarantine Manual Release Portal -->
            <div class="card">
                <div class="card-title">Quarantine Release multi-sig Portal</div>
                <form id="override-form" onsubmit="submitOverride(event)">
                    <div class="form-group">
                        <label for="operator">Operator Name</label>
                        <input type="text" id="operator" placeholder="steward_omega" required>
                    </div>
                    <div class="form-group">
                        <label for="reason">Bypass Overrides Rationale</label>
                        <textarea id="reason" placeholder="Simulated recovery of offline OPA sidecar" rows="3" required></textarea>
                    </div>
                    <div class="form-group">
                        <label for="signature">Cryptographic Override Key (NIST P-256 Base64)</label>
                        <input type="text" id="signature" placeholder="sig:steward-omega-override-key" required>
                    </div>
                    <button type="submit">Execute Multi-Sig Override</button>
                </form>
                <div style="margin-top:16px;">
                    <button onclick="clearOverrides()" style="background:rgba(239, 68, 68, 0.1); border:1px solid rgba(239, 68, 68, 0.2); color:var(--error-color);">Clear Emergency Overrides</button>
                </div>
            </div>

            <!-- Shallow Incident Guides -->
            <div class="card">
                <div class="card-title">Shallow Incident Path Recovery Guides</div>
                <div class="guides-grid">
                    <div class="guide-card" onclick="runIncidentGuide('RECOVERY')">
                        <h5>Hard Ledger Replay</h5>
                        <p>Initiate complete chronologically consistent replay of WAL logs to recover state drift.</p>
                    </div>
                    <div class="guide-card" onclick="runIncidentGuide('ROTATE')">
                        <h5>Rotate Admin Keys</h5>
                        <p>Invalidate all current P-256 keys and rotate administrative signing signatures.</p>
                    </div>
                </div>
            </div>
        </div>
    </main>

    <script>
        async function fetchState() {
            try {
                const res = await fetch('/api/status');
                const data = await res.json();

                // Update system status
                const dot = document.getElementById('system-dot');
                const text = document.getElementById('system-state-text');
                
                const nodeActive = document.getElementById('node-active');
                const nodeQuarantine = document.getElementById('node-quarantined');

                if (data.state === 'ACTIVE') {
                    dot.style.backgroundColor = 'var(--success-color)';
                    dot.style.boxShadow = '0 0 12px var(--success-color)';
                    text.innerText = 'ACTIVE STATE';
                    nodeActive.classList.add('active-state');
                    nodeQuarantine.classList.remove('quarantined-state');
                } else {
                    dot.style.backgroundColor = 'var(--error-color)';
                    dot.style.boxShadow = '0 0 12px var(--error-color)';
                    text.innerText = 'QUARANTINED LOCKDOWN';
                    nodeActive.classList.remove('active-state');
                    nodeQuarantine.classList.add('quarantined-state');
                }

                // Update WAL logs
                const tbody = document.getElementById('wal-log-body');
                tbody.innerHTML = '';
                data.walLogs.forEach(log => {
                    const tr = document.createElement('tr');
                    tr.className = 'log-row';
                    tr.innerHTML = \`
                        <td>\${log.seq}</td>
                        <td style="color:var(--primary-accent);">\${log.type}</td>
                        <td><span style="font-family:'JetBrains Mono'; font-size:11px;">\${log.payload}</span></td>
                        <td><span class="status-badge \${log.status.toLowerCase()}">\${log.status}</span></td>
                    \`;
                    tbody.appendChild(tr);
                });
            } catch (e) {}
        }

        function inspectState(state) {
            const title = document.getElementById('inspector-title');
            const desc = document.getElementById('inspector-desc');

            if (state === 'ACTIVE') {
                title.innerText = 'ACTIVE State Active Invariants';
                desc.innerText = 'Single-writer active lease ownership validated. Full write path enabled. PostgreSQL PL/pgSQL fencing, append-only, and outbox Merkle chaining actively enforced. Epoch alignment is matching active lease generation terms.';
            } else if (state === 'READ_ONLY') {
                title.innerText = 'READ_ONLY State Active Invariants';
                desc.innerText = 'Leader lease has expired or V8 GC scheduler delay has triggered step-down protection. Write routing is blocked at the application level. Local nodes can perform read queries but must not append to the ledger blocks.';
            } else if (state === 'QUARANTINED') {
                title.innerText = 'QUARANTINED State Active Invariants';
                desc.innerText = 'Cryptographic checksum mismatch or direct storage bit-rot/unauthorized WAL modifications detected on node boot. Storage engine is physically locked down. System rejects all mutations and reads until an SRE override resolves quarantine.';
            }
        }

        async function submitOverride(e) {
            e.preventDefault();
            const operator = document.getElementById('operator').value;
            const reason = document.getElementById('reason').value;
            const signature = document.getElementById('signature').value;

            try {
                const res = await fetch('/api/override', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ operator, signature, reason })
                });
                const data = await res.json();
                if (data.success) {
                    alert('Override registered successfully!');
                    fetchState();
                } else {
                    alert('Failed to register override: ' + data.error);
                }
            } catch (err) {
                alert('Error submitting override.');
            }
        }

        async function clearOverrides() {
            try {
                const res = await fetch('/api/clear-overrides', { method: 'POST' });
                const data = await res.json();
                if (data.success) {
                    alert('Emergency overrides cleared successfully. Quarantine rules restored.');
                    fetchState();
                }
            } catch (err) {
                alert('Error clearing overrides.');
            }
        }

        function runIncidentGuide(type) {
            if (type === 'RECOVERY') {
                alert('Incident Recovery Script: Replaying WAL ledger sequences... Sequence alignment completely healthy.');
            } else if (type === 'ROTATE') {
                alert('Incident Key Rotation Script: Rotated administrator NIST P-256 keys. Updated local trust-chain manifests.');
            }
        }

        // Poll status every 2 seconds
        setInterval(fetchState, 2000);
        fetchState();
    </script>
</body>
</html>
        `;
    }

    public start(): Promise<void> {
        return new Promise((resolve) => {
            this.server = this.app.listen(this.port, () => {
                console.log(`[Observatory] Premium local SRE operator observatory listening on http://localhost:${this.port}`);
                resolve();
            });
        });
    }

    public stop(): Promise<void> {
        return new Promise((resolve) => {
            if (this.server) {
                this.server.close(() => {
                    console.log('[Observatory] Server shut down.');
                    resolve();
                });
            } else {
                resolve();
            }
        });
    }
}

import axios from 'axios';
import fs from 'fs';
import path from 'path';
import crypto from 'crypto';

import { fileURLToPath } from 'url';
import { dirname } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

/**
 * ─── ZTAN OPA Rego Gateway Client ───────────────────────────────────────────
 * Validates outbox writes against the local OPA sidecar REST engine using
 * compiled Rego policies. Enforces strict fail-closed security properties.
 * ────────────────────────────────────────────────────────────────────────────
 */

export interface OpaValidationResult {
    allowed: boolean;
    reason?: string;
    quarantined: boolean;
}

export class ZtanOpaGate {
    private opaEndpoint: string;
    private regoPolicyPath: string;
    private failClosed = true;

    constructor(
        opaEndpoint = 'http://localhost:8181/v1/data/ztan/safety',
        regoPolicyPath?: string
    ) {
        this.opaEndpoint = opaEndpoint;
        this.regoPolicyPath = regoPolicyPath || path.resolve(__dirname, 'policy/ztan_safety.rego');
    }

    /**
     * Verifies the compiled Rego policy file's integrity against expected hashes
     */
    public verifyPolicyIntegrity(approvedPolicyHash: string): boolean {
        if (!fs.existsSync(this.regoPolicyPath)) {
            console.error(`[OPA Gate] Rego policy file missing: ${this.regoPolicyPath}`);
            return false;
        }
        const fileContent = fs.readFileSync(this.regoPolicyPath);
        const computedHash = crypto.createHash('sha256').update(fileContent).digest('hex');
        const matched = computedHash === approvedPolicyHash;
        if (!matched) {
            console.error(`[OPA Gate] Cryptographic drift detected on Rego Policy! Expected: ${approvedPolicyHash}, Computed: ${computedHash}`);
        }
        return matched;
    }

    /**
     * Evaluate transactional write inputs against OPA engine
     */
    public async validateWrite(input: {
        payload: string;
        operator: string;
        signature: string;
    }, workspaceRoot: string): Promise<OpaValidationResult> {
        // First check for active emergency overrides in exceptions_ledger.json
        const exceptionLedgerPath = path.resolve(workspaceRoot, 'db/exceptions_ledger.json');
        let hasActiveOverride = false;
        if (fs.existsSync(exceptionLedgerPath)) {
            try {
                const rawContent = fs.readFileSync(exceptionLedgerPath, 'utf-8');
                const exceptions = JSON.parse(rawContent);
                const now = new Date();
                
                // If any unexpired exception matches OPA-Gate bypass, we allow it
                const activeBypass = exceptions.find((e: any) => 
                    e.targetInvariant === 'OPA-Gate' && 
                    now.getTime() < new Date(e.expiresAt).getTime()
                );
                if (activeBypass) {
                    hasActiveOverride = true;
                    console.warn(`[OPA Gate] Active SRE Exception Override detected: "${activeBypass.bypassId}". Bypassing OPA checks.`);
                }
            } catch (e) {}
        }

        try {
            const response = await axios.post(this.opaEndpoint, { input }, { timeout: 2000 });
            
            if (response.status === 200 && response.data && response.data.result) {
                const isAllowed = response.data.result.allow === true;
                return {
                    allowed: isAllowed,
                    reason: isAllowed ? undefined : '[OPA_POLICY_DENIAL] Transaction violates safety policies defined in Rego rules.',
                    quarantined: !isAllowed
                };
            }

            throw new Error(`OPA sidecar returned invalid response structure: ${JSON.stringify(response.data)}`);
        } catch (err: any) {
            console.error(`[OPA Gate] Fail-Closed Intervention: OPA Sidecar query failed: ${err.message}`);
            
            if (hasActiveOverride) {
                return {
                    allowed: true,
                    reason: '[OPA_BYPASS] OPA sidecar went offline but active SRE exception bypass allowed connection.',
                    quarantined: false
                };
            }

            // Strictly fail-closed: lock node down in quarantine mode if OPA sidecar is unreachable
            return {
                allowed: false,
                reason: `[OPA_FAIL_CLOSED] OPA sidecar unreachable or errored. Fail-closed safety activated. Error: ${err.message}`,
                quarantined: true
            };
        }
    }

    public setFailClosed(enabled: boolean) {
        this.failClosed = enabled;
    }
}

import fs from 'fs';
import path from 'path';
import { verifyConfigChecksums } from './config-checksum';
import { auditEnvironmentVariables, loadAndVerifyComplianceLedger } from './ledger-verifier';

/**
 * ─── Startup Attestation Engine ─────────────────────────────────────────────
 * The primary mechanical boot validation gateway. Integrates environment audits,
 * config checksumming, and exception ledger expiration verifications.
 * ────────────────────────────────────────────────────────────────────────────
 */

export interface ExceptionRecord {
    bypassId: string;
    targetInvariant: string;
    createdAt: string; // ISO String
    expiresAt: string; // ISO String
    operatorSignature: string;
    reason: string;
}

export function performStartupAttestation(workspaceRoot: string): { 
    success: boolean; 
    status: 'ACTIVE' | 'QUARANTINED'; 
    errors: string[]; 
    telemetry: any; 
} {
    const errors: string[] = [];
    const telemetry: any = {};

    // 1. Audit Environment Variables
    const envAudit = auditEnvironmentVariables();
    telemetry.envAudit = envAudit.activeVars;
    if (!envAudit.success) {
        errors.push(...envAudit.errors);
    }

    // 2. Verify Config Checksums against Cryptographically Signed Compliance Ledger
    try {
        const approvedLedger = loadAndVerifyComplianceLedger(workspaceRoot);
        const configAudit = verifyConfigChecksums(workspaceRoot, approvedLedger.approvedConfigHashes);
        telemetry.configAudit = configAudit.computedHashes;
        if (!configAudit.success) {
            errors.push(...configAudit.errors);
        }
    } catch (ledgerError: any) {
        errors.push(`[COMPLIANCE_ERROR] Attestation failed. Signed compliance ledger verification failed: ${ledgerError.message}`);
    }

    // 3. Audit Active Emergency Exception Bypasses
    const exceptionLedgerPath = path.resolve(workspaceRoot, 'db/exceptions_ledger.json');
    if (fs.existsSync(exceptionLedgerPath)) {
        try {
            const rawContent = fs.readFileSync(exceptionLedgerPath, 'utf-8');
            const exceptions: ExceptionRecord[] = JSON.parse(rawContent);
            const now = new Date();

            for (const exception of exceptions) {
                const createdDate = new Date(exception.createdAt);
                const expiryDate = new Date(exception.expiresAt);

                // Enforce maximum 72-hour bypass duration constraint
                const durationMs = expiryDate.getTime() - createdDate.getTime();
                const maxDurationMs = 72 * 60 * 60 * 1000; // 72 hours

                if (durationMs > maxDurationMs) {
                    errors.push(`[EXCEPTION_ERROR] Exception "${exception.bypassId}" exceeds maximum 72-hour duration ceiling.`);
