                    // Synchronous wait of 50ms
                    const start = Date.now();
                    while (Date.now() - start < 50) {}
                }
            }
        }
    }

    async run() {
        logger.info('🏁 [TEST] Starting Phase S: Durable Workflow Orchestration Tests');
        let passed = 0;
        let total = 0;

