                nodeId: 'node-b',
                nodeSoftwareVersion: '2.0.0',
                supportedWorkflows: { 'auth-flow': ['2.0.0'] }
            });

            // Assert routing queries
            const targetNodeForV1 = coordinator.getCompatibleNode('auth-flow', '1.0.0');
